import{_ as t,o,c as d,a3 as a}from"./chunks/framework.D4gszBK_.js";const u=JSON.parse('{"title":"Design system","description":"","frontmatter":{},"headers":[],"relativePath":"docs/design-system.md","filePath":"docs/design-system.md"}'),r={name:"docs/design-system.md"};function s(n,e,i,c,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="design-system" tabindex="-1">Design system <a class="header-anchor" href="#design-system" aria-label="Permalink to &quot;Design system&quot;">​</a></h1><p>The app is calm and rounded, like the plush: one blue accent for actions, white or near-white surfaces, and only Poulpy and the Home header tint with his mood. Values live in <a href="https://github.com/tkint/coach-poulpy/blob/main/design/tokens.json" target="_blank" rel="noreferrer"><code>design/tokens.json</code></a> and are generated into each platform (see <a href="./../design/README"><code>design/README.md</code></a>); this page says how to use them. The live swatches are on the site&#39;s Tokens page.</p><h2 id="colour-roles" tabindex="-1">Colour roles <a class="header-anchor" href="#colour-roles" aria-label="Permalink to &quot;Colour roles&quot;">​</a></h2><p>Use roles, never raw palette steps, in screens. Each role has a light and a dark value.</p><table tabindex="0"><thead><tr><th>Role</th><th>Use it for</th></tr></thead><tbody><tr><td><code>primary</code> / <code>onPrimary</code></td><td>The main action on a screen (Start session, Save), selected chips, links, progress</td></tr><tr><td><code>primaryContainer</code> / <code>onPrimaryContainer</code></td><td>Tonal buttons, selected rows, Poulpy&#39;s speech on the blue side</td></tr><tr><td><code>grumpy</code> / <code>onGrumpy</code></td><td>The one action offered while Poulpy is on the ember side (Catch up, Flip him back)</td></tr><tr><td><code>grumpyContainer</code> / <code>onGrumpyContainer</code></td><td>The Home header and cards while Poulpy is on the ember side</td></tr><tr><td><code>background</code>, <code>surface</code>, <code>surfaceVariant</code></td><td>Screen, cards and sheets, inset fields and steppers</td></tr><tr><td><code>onSurfaceVariant</code>, <code>outline</code></td><td>Secondary text and captions; card borders and dividers</td></tr><tr><td><code>success</code></td><td>A confirmed save or a finished phase, with a check icon</td></tr><tr><td><code>error</code> / <code>onError</code></td><td>Errors only: crimson, always with an icon and words</td></tr><tr><td><code>heat1</code>, <code>heat2</code>, <code>heat3</code></td><td>How much a workout works each muscle on the body map, from a little to most. Orange, on the body map only: never for Poulpy&#39;s moods</td></tr><tr><td><code>pain</code></td><td>A worked area that hurts, outlined on the body map. Purple, so it reads apart from the heat and is never mistaken for an error</td></tr></tbody></table><p>Rules:</p><ul><li><code>poulpy.blue</code>, <code>poulpy.ember</code> and <code>poulpy.ink</code> are Poulpy&#39;s fabric and never change between light and dark.</li><li>The plush blue and ember are too light for white text: buttons use <code>primary</code> and <code>grumpy</code>.</li><li>Ember means &quot;a session slipped&quot;, never &quot;something broke&quot;. An error is crimson, so a cross Poulpy is never read as a failure.</li><li>Colours that must be told apart also differ in lightness, not hue alone.</li></ul><h2 id="mood-shades" tabindex="-1">Mood shades <a class="header-anchor" href="#mood-shades" aria-label="Permalink to &quot;Mood shades&quot;">​</a></h2><p>Six shades, from <code>mood.*</code>, only on Poulpy himself, the Home header tint and mood-coloured charts:</p><table tabindex="0"><thead><tr><th>Side</th><th>Shades, calmest to strongest</th></tr></thead><tbody><tr><td>Blue (on track)</td><td><code>recovering</code>, <code>happy</code>, <code>proud</code></td></tr><tr><td>Ember (a session slipped)</td><td><code>annoyed</code>, <code>grumpy</code>, <code>fuming</code></td></tr></tbody></table><p>Which shade shows when is in <a href="./brand#moods">Brand</a>.</p><h2 id="type" tabindex="-1">Type <a class="header-anchor" href="#type" aria-label="Permalink to &quot;Type&quot;">​</a></h2><p>Baloo 2 for display and titles, Nunito for everything else. Platforms map each role to a system text style so Dynamic Type and font scaling keep working (<code>.font(.poulpy(.headline))</code> on iOS, <code>MaterialTheme.typography</code> on Android).</p><table tabindex="0"><thead><tr><th>Role</th><th>Font</th><th>Size / line</th><th>Use</th></tr></thead><tbody><tr><td><code>display</code></td><td>Baloo 2 800</td><td>40 / 44</td><td>Poulpy&#39;s line on Home, end-of-session headline</td></tr><tr><td><code>title</code></td><td>Baloo 2 700</td><td>28 / 32</td><td>Screen titles, workout name on its page</td></tr><tr><td><code>headline</code></td><td>Baloo 2 700</td><td>21 / 25</td><td>Section heads, the current exercise in the player</td></tr><tr><td><code>body</code></td><td>Nunito 500</td><td>16 / 24</td><td>Everything you read</td></tr><tr><td><code>label</code></td><td>Nunito 800, tracked 0.08 em, upper case</td><td>12.5 / 16</td><td>Eyebrows, tab labels, &quot;Next up&quot;</td></tr><tr><td><code>timer</code></td><td>Nunito 800, tabular figures</td><td>64 / 64</td><td>Timers and rep counts, which must not jitter</td></tr></tbody></table><p><strong>Words never break.</strong> Translations run longer than English (« Bibliothèque », « Échauffement »), so text is laid out for any length:</p><ul><li>Text in a space of fixed width (tab labels, chips, stat tiles, stepper values) stays on one line and shrinks to fit, never below 9 sp / pt; past that it ends in an ellipsis. <code>FitText</code> on Android, <code>.lineLimit(1).minimumScaleFactor(…)</code> on iOS, whose tab bar already does it.</li><li>Buttons wrap their label between words rather than shrink it.</li><li>Every other text wraps between words only, never inside one, and never hyphenates.</li></ul><h2 id="space-radius-motion" tabindex="-1">Space, radius, motion <a class="header-anchor" href="#space-radius-motion" aria-label="Permalink to &quot;Space, radius, motion&quot;">​</a></h2><ul><li>Spacing steps: 4, 8, 12, 16, 24, 32, 48 (<code>xs</code> to <code>xxxl</code>). Pick a step; never a value between them.</li><li>Radius: 8 for chips and small fields, 10 for cards and rows, 14 for sheets, pill for buttons. Small cards stay close to square so their text reads first.</li><li>Controls stay compact: a standard button is 44 high, a large one 52, an icon button 40 (its touch area stays 44), a small button 34. The side gutter of a screen is 16, and rows are 56 high with a 32 to 40 avatar. In the apps these come from one place, <code>PoulpySize</code> (generated from <code>design/tokens.json</code>, next to <code>PoulpySpace</code> and <code>PoulpyRadius</code>); a screen never writes a literal height, gutter or corner radius.</li><li>Motion: the flip (700 ms with overshoot) is the one signature move, used only when Poulpy changes side. Mood shades fade in 300 ms. Everything else is 150 to 250 ms and plain. With reduced motion on, the loader slows to one turn in 10 s.</li></ul><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Shape</th><th>Notes</th></tr></thead><tbody><tr><td>Primary button</td><td>44 high, pill, <code>primary</code></td><td>One per screen</td></tr><tr><td>Tonal button</td><td>44 high, pill, <code>primaryContainer</code></td><td>Secondary actions</td></tr><tr><td>Outline button</td><td>44 high, pill, 2 px <code>outline</code></td><td>Cancel, less important choices</td></tr><tr><td>Grumpy button</td><td>44 high, pill, <code>grumpy</code></td><td>Only the catch-up action while Poulpy is ember</td></tr><tr><td>Chip</td><td>32 high, pill; on = <code>primary</code>, off = 1.5 px <code>outline</code></td><td>Filters (muscle, equipment, format), with <code>aria-pressed</code> or selected state; <code>PoulpyChip</code> on both platforms</td></tr><tr><td>Choosing one value</td><td>A select field that opens a sheet for a longer list, or a native menu for a short one</td><td>Pills and chips are for filters and for view switches; a form asks for a value with a select, never a row of pills</td></tr><tr><td>Search field</td><td>44 high, pill, 1.5 px <code>outline</code>, <code>primary</code> while it holds text, a round clear button</td><td><code>PillSearchField</code> on both platforms</td></tr><tr><td>Stepper</td><td>Inset <code>surfaceVariant</code> box, label, minus and plus round buttons of 44</td><td>Sets, reps, load, rest</td></tr><tr><td>Pattern badge</td><td>44 round, <code>primaryContainer</code>, one icon per movement pattern in <code>onPrimaryContainer</code></td><td>Stands in for exercise pictures until real images exist</td></tr><tr><td>Filter row</td><td>Search field, a row of chips, then the count line with one action at its right</td><td><code>ListFilters</code> on both platforms, shared by the exercise and workout lists</td></tr><tr><td>Poulpy card</td><td>14 radius, <code>primaryContainer</code>, Poulpy happy on the blue side, a title, a line and one primary button</td><td><code>PoulpyCard</code>: no results, an empty list</td></tr><tr><td>Item menu</td><td>A long press (iOS context menu) or ⋮; actions with icons, a divider, then the destructive one</td><td>Destructive items and their confirmation are <code>error</code> with an icon, never ember; the confirmation says what goes and what stays</td></tr><tr><td>Plan sheet</td><td>14 radius sheet, a month from Monday; past days dimmed, today outlined, planned days <code>primary</code></td><td><code>PlanSheet</code> on both platforms; tick several days, save once</td></tr><tr><td>Error banner</td><td><code>error</code> tint, icon plus text</td><td>Never ember</td></tr><tr><td>Loader</td><td>Poulpy from above, a blue outline of eight lobes, one turn every 2.4 s</td><td><code>PoulpyLoader</code> on both platforms; replaces spinners</td></tr></tbody></table><h2 id="base-fields" tabindex="-1">Base fields <a class="header-anchor" href="#base-fields" aria-label="Permalink to &quot;Base fields&quot;">​</a></h2><p>The fields every form is built from. Reference mockups: <code>profile-edit</code>, the three <code>profile-*-sheet</code> pages, <code>body-log-sheet</code>, <code>body-log-height-sheet</code>. CSS classes are in <code>design/mockups/shared/mockup.css</code>. Build every new form from these, and move old screens to them as they are touched.</p><table tabindex="0"><thead><tr><th>Field</th><th>Shape</th><th>Behaviour</th></tr></thead><tbody><tr><td><a href="https://tkint.github.io/coach-poulpy/mobile-components#text-field" target="_blank" rel="noreferrer">Text field</a></td><td>46 high, 8 radius, 1.5 px <code>outline</code>, label above, <code>primary</code> outline on focus</td><td>Free text: a name. A note under it in <code>onSurfaceVariant</code></td></tr><tr><td><a href="https://tkint.github.io/coach-poulpy/mobile-components#select-field" target="_blank" rel="noreferrer">Select field</a></td><td>Same box, the chosen value (or a muted &quot;Not set&quot;) and a chevron</td><td>Tapping opens a sheet; nothing else is shown on the screen. Never a row of pills</td></tr><tr><td><a href="https://tkint.github.io/coach-poulpy/mobile-components#option-sheet" target="_blank" rel="noreferrer">Option sheet</a></td><td>14 radius sheet, a title, one row per choice</td><td>Single choice: a radio and the sheet closes on tap. Several choices: checkboxes and a Done button. A choice that needs text (Custom pronouns) shows its text field inside the sheet</td></tr><tr><td><a href="https://tkint.github.io/coach-poulpy/mobile-components#number-field" target="_blank" rel="noreferrer">Number field</a></td><td>Text field with a unit at its right (<code>bpm</code>, <code>kg</code>, <code>cm</code>)</td><td>Selects all its text on focus, opens the numeric keyboard, checks the range on leaving. Optional round − and + buttons on both sides (the <code>number-entry</code> pattern) for small nudges. Imperial height is two number fields, ft and in. Every numeric value in the app uses it, including the builder&#39;s sets, reps, rest between sets, rest and weight (<code>builder-sets-edit-step</code>, <code>builder-circuit-edit-step</code>); the − and + step by the same amount as before, and the typed value keeps the same limits</td></tr><tr><td><a href="https://tkint.github.io/coach-poulpy/mobile-components#step-slider" target="_blank" rel="noreferrer">Step slider</a></td><td>A bar of dots, <code>•--•--•--•--•</code>, the current label above it, the two ends named below</td><td>A fixed scale of five or fewer named steps, inside an option sheet</td></tr><tr><td>Password field (draft, #272)</td><td>Text field with a show or hide eye button inside its right end; a hint under it (<code>8 characters or more.</code>)</td><td><code>password-field</code> in the mockups. Errors under a field are <code>error</code> text with an icon and the field outline turns <code>error</code>; a message about the whole form is an error card (<code>error</code> outline and text on <code>surfaceVariant</code>, with an icon)</td></tr><tr><td><a href="https://tkint.github.io/coach-poulpy/mobile-components#line-chart" target="_blank" rel="noreferrer">Line chart</a></td><td>Grid lines behind the line, the unit at the top of the axis, a value at each grid line, the date range under it</td><td>No grid colour that implies good or bad; a weight going up is never red</td></tr><tr><td><a href="https://tkint.github.io/coach-poulpy/mobile-components#empty-chart-card" target="_blank" rel="noreferrer">Empty chart card</a></td><td><code>PoulpyCard</code> shape with Poulpy on the blue side, a line and the one action that adds the first entry</td><td>Shown instead of the chart when nothing is logged</td></tr><tr><td>Body map</td><td>A front and a back figure, drawn in the build the person chose in the profile, as a muscle chart with transparent skin, side by side, each area a shape that fills with <code>primary</code> when picked; left and right are separate areas</td><td>Every area is a checkbox with a name (&quot;Left knee&quot;), so a screen reader and the text summary under the figure say the same. Left is the person&#39;s left: the right half of the front figure and the left half of the back one. Used to say where it hurts, and to show what an exercise works</td></tr><tr><td>Body map heat map (<a href="https://github.com/tkint/coach-poulpy/issues/244" target="_blank" rel="noreferrer">#244</a>, built in #326)</td><td>The body map read-only for a whole workout: areas it doesn&#39;t work are outlines only, worked areas fill with <code>heat1</code>, <code>heat2</code> or <code>heat3</code> by sets per muscle group compared with the most-worked one (below 40 %, from 40 %, from 75 %); a worked area that hurts gets a 3 px <code>pain</code> outline on a <code>background</code> halo, drawn above its neighbours; a Less / More legend, with Hurts when something hurts</td><td>The figure is one image whose label is the text summary (&quot;shoulders and triceps most, then chest, back and biceps, a little core&quot;), and the heat steps differ in lightness, so nothing depends on colour alone. On the workout page; the format and equipment badges sit under the workout name in the sheet</td></tr><tr><td>Details sheet (<a href="https://github.com/tkint/coach-poulpy/issues/244" target="_blank" rel="noreferrer">#244</a>, built in #326)</td><td>14 radius sheet over the body map with no scrim; a handle, the workout name at its top, its content, then the action bar</td><td>Three stops (peek, half, full), the handle drags or taps between them: dragged down it shows only the name and actions under a full-screen map; half up by default; full screen its content scrolls, and scrolling down past its top drags the sheet back down. The map keeps the size it has at half while the sheet goes higher. The back and menu buttons float above it at every stop</td></tr><tr><td>Plan summary (<a href="https://github.com/tkint/coach-poulpy/issues/244" target="_blank" rel="noreferrer">#244</a>, built in #326)</td><td><code>primaryContainer</code> row: a calendar icon, &quot;3 sessions planned&quot; over &quot;Next on Fri 30 Oct&quot;, and a Change days button</td><td>Replaces one pill per planned day on the workout page</td></tr></tbody></table><h2 id="screens" tabindex="-1">Screens <a class="header-anchor" href="#screens" aria-label="Permalink to &quot;Screens&quot;">​</a></h2><p>Mockups are plain HTML in <code>design/mockups/</code> (<a href="./adr/0016-mockups-are-plain-html-in-the-repo">ADR 0016</a>). They are split by stage (<code>drafts/</code> and <code>agreed/</code>) and platform (<code>phone/</code>, <code>tablet/</code>, <code>web/</code>).</p><ul><li>Build from an agreed mockup. If a screen has none, agree one through a PR before building it.</li><li>The <a href="https://tkint.github.io/coach-poulpy/mockups/" target="_blank" rel="noreferrer">Mockups gallery</a> shows each app view and its available states in light and dark themes.</li><li>CI checks mockup links, local assets, design tokens and required metadata with <code>node design/check-mockups.mjs</code>.</li></ul><p>The mockup is the design reference; this page defines the shared rules and components used to build it.</p><h2 id="websites" tabindex="-1">Websites <a class="header-anchor" href="#websites" aria-label="Permalink to &quot;Websites&quot;">​</a></h2><p>The landing site, the web app, the web mockups and the docs site share one package, <code>web/ui</code>: DaisyUI with the Poulpy theme and a few Vue components (<a href="./adr/0023-the-websites-share-one-vue-and-daisyui-design-system">ADR 0023</a>). The live samples and the class of each component are on the <a href="https://tkint.github.io/coach-poulpy/web-components" target="_blank" rel="noreferrer">Web components</a> page.</p><ul><li>Use the shared components (<code>CpButton</code>, <code>CpChip</code>...) in Vue, and their classes in a web mockup; never restyle a DaisyUI class in an app. A missing shape goes in <code>web/ui</code>, with its sample and its section on the Web components page in the same PR.</li><li>Every DaisyUI class carries the <code>cp-</code> prefix (<code>cp-btn cp-btn-primary</code>). Our own classes (<code>cp-chip</code>, <code>cp-stepper</code>, <code>cp-type-label</code>...) never reuse a DaisyUI name, so the two cannot clash.</li><li>The roles above keep their meaning: <code>cp-btn-primary</code> is <code>primary</code>, <code>cp-btn-secondary</code> is the tonal <code>primaryContainer</code>, <code>cp-btn-accent</code> is <code>grumpy</code> and only for the catch-up action. Never use DaisyUI&#39;s <code>warning</code> classes: ember is not a warning, and a problem is an <code>error</code>.</li><li>A web mockup that fills the browser window, such as one with a <code>CpDrawer</code> sidebar, adds <code>&lt;meta name=&quot;mockup:viewport&quot; content=&quot;800&quot;&gt;</code>: the docs site then shows it in a window of that height and the page scrolls inside it, since a frame sized to a page as tall as the frame would grow forever. <code>design/mockups/shared/mockup-drawer.js</code> opens such a drawer on a large screen. Web mockups link <code>web/ui/src/tokens.css</code> then <code>web/ui/poulpy-ui.css</code>. The generated CSS is ignored by Git: the web and docs-site builds generate it from <code>web/ui/src/</code>, and the docs build copies it alongside the mockups into the published site.</li><li>Phone and tablet mockups keep <code>design/mockups/shared/mockup.css</code>: they draw the native screens.</li><li>Icons on the websites and in every mockup come from Lucide, as in the <a href="#icons">Icons</a> section (<a href="./adr/0024-lucide-is-the-icon-set">ADR 0024</a>).</li></ul><h2 id="icons" tabindex="-1">Icons <a class="header-anchor" href="#icons" aria-label="Permalink to &quot;Icons&quot;">​</a></h2><p>Every icon is from <a href="https://lucide.dev" target="_blank" rel="noreferrer">Lucide</a>, on every platform (<a href="./adr/0024-lucide-is-the-icon-set">ADR 0024</a>). Use its name for the action, never a home-made drawing of one Lucide already has. Icons take their colour from the roles above, and an error keeps its icon. Lucide&#39;s drawing stays as it is: a 24 box and a 2 wide round stroke, never filled; only the size changes (24 by default, 20 in chips and small buttons, 16 to 18 beside a line of text).</p><table tabindex="0"><thead><tr><th>Where</th><th>How</th></tr></thead><tbody><tr><td>Vue (web app, <code>web/ui</code>, docs site)</td><td><code>@lucide/vue</code>: <code>&lt;ChevronLeft class=&quot;size-5&quot; aria-hidden=&quot;true&quot; /&gt;</code></td></tr><tr><td>Mockups</td><td>The Lucide SVG inline, with <code>data-lucide=&quot;chevron-left&quot;</code>; <code>design/check-mockups.mjs</code> checks it</td></tr><tr><td>Android</td><td><code>Icon(Lucide.ChevronLeft, contentDescription = …)</code></td></tr><tr><td>iOS</td><td><code>LucideIcon(.chevronLeft, size: 20)</code>, or <code>Label(&quot;action.back&quot;, lucide: .chevronLeft)</code></td></tr></tbody></table><p>The Android and iOS icons, and the reference copies the mockups are checked against, are generated from <code>design/icons/</code>: run <code>node design/build-icons.mjs --add &lt;name&gt;</code> for an icon not used yet.</p><p>One icon per meaning, the same on every platform:</p><table tabindex="0"><thead><tr><th>Meaning</th><th>Lucide icon</th></tr></thead><tbody><tr><td>Back, previous; next, open a row</td><td><code>chevron-left</code>; <code>chevron-right</code></td></tr><tr><td>Close, clear</td><td><code>x</code></td></tr><tr><td>More actions</td><td><code>ellipsis-vertical</code></td></tr><tr><td>Add; duplicate, copy</td><td><code>plus</code>; <code>copy</code></td></tr><tr><td>Edit; delete</td><td><code>pencil</code>; <code>trash</code></td></tr><tr><td>Share; export a file</td><td><code>share-2</code>; <code>download</code></td></tr><tr><td>Plan a day</td><td><code>calendar-plus</code></td></tr><tr><td>Error</td><td><code>circle-exclamation-point</code></td></tr><tr><td>Tabs: Home, Library, Live, History, Settings</td><td><code>house</code>, <code>library-big</code>, <code>activity</code>, <code>rotate-ccw-clock</code>, <code>settings</code></td></tr><tr><td>Warm-up, work, cool down</td><td><code>sun</code>, <code>zap</code>, <code>moon</code></td></tr><tr><td>Circuit, sets</td><td><code>repeat</code>, <code>list</code></td></tr><tr><td>Treadmill (no Lucide treadmill), foot pod, heart rate band</td><td><code>gauge</code>, <code>footprints</code>, <code>heart-pulse</code></td></tr><tr><td>Filters: equipment, focus, position, zones, tags</td><td><code>dumbbell</code>, <code>target</code>, <code>armchair</code>, <code>person-standing</code>, <code>tag</code></td></tr></tbody></table><p>The movement-pattern badge stands in for exercise pictures, and Lucide draws few people, so its icons are the nearest Lucide match rather than an exact one: squat <code>person-standing</code>, hinge <code>hand-grab</code>, lunge <code>footprints</code>, push <code>dumbbell</code>, pull <code>biceps-flexed</code>, carry <code>luggage</code>, core <code>shield</code>, rotation <code>rotate-cw</code>, locomotion <code>sport-shoe</code>, mobility <code>accessibility</code>, stretch <code>stretch-horizontal</code>.</p><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h2><ul><li>Touch targets at least 44 by 44; a visually smaller control, such as the 40 icon button, extends its touch area to 44.</li><li>Text contrast at least 4.5:1, including small grey labels; 3:1 only for text 24 px and up.</li><li>Every icon-only button has a label; decorative drawings of Poulpy are hidden from screen readers, and a pose that carries meaning has a description.</li><li>Nothing depends on colour alone: mood changes also change Poulpy&#39;s face and words, errors carry an icon.</li></ul>',39)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
